package br.com.confirmacao.scheduleblock.application;
import br.com.confirmacao.professional.application.ProfessionalNotFoundException;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.scheduleblock.domain.ScheduleBlock;import br.com.confirmacao.scheduleblock.infrastructure.ScheduleBlockRepository;import br.com.confirmacao.session.application.SessionConflictException;import br.com.confirmacao.session.domain.SessionStatus;import br.com.confirmacao.session.infrastructure.SessionAppointmentRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;
@Service public class ScheduleBlockService{private final ScheduleBlockRepository blocks;private final SessionAppointmentRepository sessions;private final ProfessionalRepository professionals;public ScheduleBlockService(ScheduleBlockRepository b,SessionAppointmentRepository s,ProfessionalRepository p){blocks=b;sessions=s;professionals=p;}@Transactional(readOnly=true)public List<ScheduleBlock> find(UUID professionalId,Instant start,Instant end){if(start==null||end==null||!end.isAfter(start))throw new IllegalArgumentException("Período de consulta inválido");return blocks.findAllByProfessionalIdAndStartsAtLessThanAndEndsAtGreaterThanOrderByStartsAtAsc(professionalId,end,start);}@Transactional public ScheduleBlock create(UUID professionalId,Instant start,Instant end,String reason){if(start==null||start.isBefore(Instant.now()))throw new IllegalArgumentException("Não é possível bloquear um horário que já passou");if(end==null||!end.isAfter(start))throw new IllegalArgumentException("O horário final deve ser posterior ao inicial");if(sessions.existsByProfessionalIdAndStatusNotAndStartsAtLessThanAndEndsAtGreaterThan(professionalId,SessionStatus.CANCELED,end,start))throw new SessionConflictException("Já existe uma sessão nesse horário");if(blocks.existsByProfessionalIdAndStartsAtLessThanAndEndsAtGreaterThan(professionalId,end,start))throw new SessionConflictException("Já existe um bloqueio nesse horário");var professional=professionals.findById(professionalId).orElseThrow(()->new ProfessionalNotFoundException(professionalId));return blocks.save(new ScheduleBlock(professional,start,end,reason));}@Transactional public void delete(UUID professionalId,UUID id){blocks.delete(blocks.findByIdAndProfessionalId(id,professionalId).orElseThrow(()->new IllegalArgumentException("Bloqueio não encontrado")));}}
